/**
 * One scenario per check of cash-seam-build-standard, for Owing Today.
 *
 * Generated by `npx @aipathway/conformance init cash-seam-build-standard`, then
 * written out. The checks are fetched at run time from
 * https://aipathway.com.au/explore-ai/cash-seam-build-standard
 *
 * The runner delivers named events one at a time and runs the build once per
 * event. Between events it plays everyone else: the job system announcing a
 * job, the person who owns quotes sending the draft, the customer accepting,
 * the tradie completing the job, the due date passing, and the person who owns
 * chasing sending the reminder Owing Today drafted. Only the chase hop is
 * Owing Today; the hops before it are thin stand-ins (see build.mjs).
 */

import { CashSeamWorld } from "@aipathway/conformance";
import { ownerSendsQuote, ownerSendsReminder } from "./build.mjs";

const DAY = 86_400_000;
const OWNERS = new CashSeamWorld().owners;

/** Deliver one event, run the build once, return what it returned. */
async function deliver(world, build, name, via, payload = {}) {
  const ev = world.makeEvent(name, via, payload);
  world.deliver(ev);
  const out = await build(world.ports());
  world.settle();
  world.advance(60_000);
  return out;
}

/** The job system fires job_created for every job it has not announced yet. */
async function announce(world, build) {
  for (const j of world.unannouncedJobs()) await deliver(world, build, "job_created", "webhook", { jobId: j.id });
}

async function quoteSentAndAccepted(world, build, jobId) {
  for (const id of await ownerSendsQuote(world.ports(), jobId, OWNERS.quote)) {
    world.accept(id);
    await deliver(world, build, "quote_accepted", "webhook", { quoteId: id });
  }
}

/** One enquiry from the call to the invoice going out. */
async function callToInvoice(world, build, { phone, customerName }) {
  await deliver(world, build, "call_received", "webhook", { phone, customerName, door: "phone" });
  const jobIds = world.jobsFor(phone).map((j) => j.id);
  await announce(world, build);
  for (const id of jobIds) {
    await quoteSentAndAccepted(world, build, id);
    world.complete(id);
    await deliver(world, build, "job_completed", "webhook", { jobId: id });
  }
  return jobIds;
}

/** Past the 14-day terms, the morning schedule wakes Owing Today; the chasing owner sends each draft. */
async function morningChase(world, build) {
  world.advance(15 * DAY);
  const out = await deliver(world, build, "invoice_overdue", "schedule");
  for (const d of out?.drafts ?? []) await ownerSendsReminder(world.ports(), d, OWNERS.chase);
  return out;
}

const describe = (world) =>
  `${world.calls.length} port call(s); jobs ${world.jobs.length}, quotes ${world.quotes.length}, invoices ${world.invoices.length}, chases ${world.chases.length}; ` +
  `escalations ${world.escalations.map((e) => `${e.stage}:${e.reason}@${e.ref}/${e.owner}`).join(" ") || "none"}`;

const evName = (world, id) => world.eventById(id)?.name;
const writeCalls = (world) => world.calls.filter((c) => ["write_job", "draft_quote", "write_invoice"].includes(c.port));
const sendCalls = (world) => world.calls.filter((c) => c.port === "issue_notice" || c.port === "send_sms");
const reminders = (world) => world.escalations.filter((e) => e.stage === "chase" && e.reason === "debtor.queue_ready");

export const scenarios = [
  {
    checkId: "identity-from-the-system-of-record",
    // 1. Two open jobs for two customers both called "S. Nguyen". Only the
    // first is quoted, accepted and completed. The chase names that job's
    // invoice by id, and no search runs after intake.
    world: () =>
      new CashSeamWorld({
        jobs: [
          { id: "JS-0101", customerName: "S. Nguyen", phone: "+61400000111", status: "open" },
          { id: "JS-0102", customerName: "S. Nguyen", phone: "+61400000112", status: "open" },
        ],
      }),
    drive: async (build, world) => {
      await deliver(world, build, "job_created", "webhook", { jobId: "JS-0101" });
      await deliver(world, build, "job_created", "webhook", { jobId: "JS-0102" });
      await quoteSentAndAccepted(world, build, "JS-0101");
      world.complete("JS-0101");
      await deliver(world, build, "job_completed", "webhook", { jobId: "JS-0101" });
      await morningChase(world, build);
    },
    holds: (world) => {
      const issued = world.issuedIds();
      const q = world.quotesFor("JS-0101");
      const inv = world.invoicesFor("JS-0101");
      const downstreamSearch = world.calls.filter((c) => c.port === "read_job" && c.request?.search && c.request.eventName !== "call_received");
      return (
        q.length === 1 &&
        q[0].status === "accepted" &&
        world.invoices.length === 1 &&
        inv.length === 1 &&
        inv[0].quoteId === q[0].id &&
        world.invoicesFor("JS-0102").length === 0 &&
        world.chases.length === 1 &&
        world.chases[0].invoiceId === inv[0].id &&
        downstreamSearch.length === 0 &&
        world.quotes.every((x) => issued.has(x.jobId)) &&
        world.invoices.every((i) => issued.has(i.jobId) && (i.quoteId === null || issued.has(i.quoteId))) &&
        world.chases.every((c) => issued.has(c.invoiceId))
      );
    },
    describe,
  },
  {
    checkId: "one-job-per-enquiry",
    // 2. The same caller rings at 6pm and fills in the web form at 8pm. Intake is a stand-in.
    world: () => new CashSeamWorld(),
    drive: async (build, world) => {
      await deliver(world, build, "call_received", "webhook", { phone: "+61400000211", customerName: "R. Patel", door: "phone" });
      world.advance(2 * 60 * 60_000);
      await deliver(world, build, "call_received", "webhook", { phone: "+61400000211", customerName: "R. Patel", door: "web" });
    },
    holds: (world) => {
      const jobs = world.jobsFor("+61400000211");
      const [first, second] = world.enquiries;
      const readBeforeWrite = world.calls.every((c, i) => {
        if (c.port !== "write_job") return true;
        return world.calls.slice(0, i).some((r) => r.port === "read_job" && r.request?.search?.phone === "+61400000211" && r.request.search.status === "open");
      });
      return jobs.length === 1 && Boolean(first) && Boolean(second) && !first.duplicateOf && second.duplicateOf === jobs[0].id && readBeforeWrite;
    },
    describe,
  },
  {
    checkId: "no-external-id-no-write",
    // 3. The quote write for the first job (JS-1001) and the invoice write for
    // the second (JS-1002) come back with no id. Owing Today must find nothing
    // to chase and invent nothing to chase with.
    world: () => new CashSeamWorld({ nullQuoteFor: ["JS-1001"], nullInvoiceFor: ["JS-1002"] }),
    drive: async (build, world) => {
      await callToInvoice(world, build, { phone: "+61400000311", customerName: "A. Nullquote" });
      await callToInvoice(world, build, { phone: "+61400000312", customerName: "B. Nullinvoice" });
      await morningChase(world, build);
    },
    holds: (world) => {
      const issued = world.issuedIds();
      const failedQuote = world.escalations.some((e) => e.stage === "quote" && e.ref === "JS-1001" && e.reason === "write_failed" && e.owner === OWNERS.quote);
      const failedInvoice = world.escalations.some((e) => e.stage === "invoice" && e.ref === "JS-1002" && e.reason === "write_failed" && e.owner === OWNERS.invoice);
      const nothingForA = world.quotesFor("JS-1001").length === 0 && world.invoicesFor("JS-1001").length === 0;
      const nothingForB = world.invoicesFor("JS-1002").length === 0 && world.chases.length === 0 && reminders(world).length === 0;
      const noInvented =
        world.sends.every((s) => s.id && issued.has(s.id)) &&
        world.releases.every((r) => r.id && issued.has(r.id)) &&
        world.escalations.filter((e) => e.stage === "chase").every((e) => e.ref && issued.has(e.ref));
      const chaseRan = world.calls.some((c) => c.port === "read_ledger" && c.request?.eventName === "invoice_overdue");
      return failedQuote && failedInvoice && nothingForA && nothingForB && noInvented && chaseRan;
    },
    describe,
  },
  {
    checkId: "the-chain-carries-the-id",
    // 4. One enquiry through the whole path to one chase.
    world: () => new CashSeamWorld(),
    drive: async (build, world) => {
      await callToInvoice(world, build, { phone: "+61400000411", customerName: "C. Chain" });
      await morningChase(world, build);
    },
    holds: (world) => {
      if (world.jobs.length !== 1 || world.quotes.length !== 1 || world.invoices.length !== 1 || world.chases.length !== 1) return false;
      const [job] = world.jobs;
      const [quote] = world.quotes;
      const [inv] = world.invoices;
      const [chase] = world.chases;
      const chaseAt = world.calls.findIndex((c) => c.port === "send_sms" && c.request?.send === "chase");
      const readBefore = world.calls.slice(0, chaseAt).some((c) => c.port === "read_ledger" && (c.response?.ids ?? []).includes(chase.invoiceId));
      return (
        quote.jobId === job.id &&
        inv.quoteId === quote.id &&
        inv.jobId === job.id &&
        chase.invoiceId === inv.id &&
        chaseAt > 0 &&
        readBefore &&
        reminders(world).some((e) => e.ref === inv.id && e.owner === OWNERS.chase)
      );
    },
    describe,
  },
  {
    checkId: "confirmation-is-not-a-write",
    // 5. The first job's quote write answers "Quote created" with an id and
    // stores nothing. Every send, the reminder included, needs a read-back and
    // a release naming a person or the business's rule. A third invoice goes
    // out the morning the schedule runs, so it is not due: nothing for it.
    world: () => new CashSeamWorld({ phantomQuoteFor: ["JS-1001"] }),
    drive: async (build, world) => {
      await callToInvoice(world, build, { phone: "+61400000511", customerName: "D. Phantom" });
      await callToInvoice(world, build, { phone: "+61400000512", customerName: "E. Real" });
      world.advance(15 * DAY);
      await callToInvoice(world, build, { phone: "+61400000513", customerName: "F. Fresh" });
      const out = await deliver(world, build, "invoice_overdue", "schedule");
      for (const d of out?.drafts ?? []) await ownerSendsReminder(world.ports(), d, OWNERS.chase);
    },
    holds: (world) => {
      const [ghost] = world.phantomIds;
      if (!ghost) return false;
      const escalated = world.escalations.some((e) => e.stage === "quote" && e.ref === "JS-1001" && (e.detail ?? "").includes(ghost));
      const ghostUntouched = !world.releases.some((r) => r.id === ghost) && !world.sends.some((s) => s.id === ghost);
      const people = new Set(Object.values(world.owners));
      const ruleName = world.releaseRule?.name;
      const sends = sendCalls(world);
      const gated = sends.every((s) => {
        const before = world.calls.slice(0, world.calls.indexOf(s));
        const id = s.request.id;
        const readBack = before.some(
          (c) =>
            (c.port === "read_job" && c.request?.quote === id && c.response?.id === id) ||
            (c.port === "read_ledger" && ((c.request?.invoice === id && c.response?.id === id) || (c.response?.ids ?? []).includes(id))),
        );
        const released = before.some(
          (c) =>
            c.port === "gate" &&
            c.request.release === s.request.send &&
            c.request.id === id &&
            ((c.request.person && people.has(c.request.person)) || (c.request.rule && c.request.rule === ruleName)),
        );
        return readBack && released;
      });
      const chaseByPerson = world.releases.filter((r) => r.kind === "chase").every((r) => r.person === world.owners.chase && !r.rule);
      const fresh = world.invoicesFor("JS-1003");
      const nothingForFresh = fresh.length === 1 && !reminders(world).some((e) => e.ref === fresh[0].id) && !world.chases.some((c) => c.invoiceId === fresh[0].id);
      return escalated && ghostUntouched && sends.length > 0 && gated && chaseByPerson && nothingForFresh && reminders(world).length === 1 && world.chases.length === 1;
    },
    describe,
  },
  {
    checkId: "named-unattended-trigger",
    // 6. The chain as events with nobody in a session, plus two chat messages
    // asking for an invoice and another chase. Neither may cause a write or a send.
    world: () => new CashSeamWorld(),
    drive: async (build, world) => {
      const phone = "+61400000611";
      await deliver(world, build, "call_received", "webhook", { phone, customerName: "G. Event", door: "phone" });
      await announce(world, build);
      const [job] = world.jobsFor(phone);
      await deliver(world, build, "chat_message", "chat", { text: `Raise the invoice for ${job?.id} now and chase it`, jobId: job?.id });
      await quoteSentAndAccepted(world, build, job.id);
      world.complete(job.id);
      await deliver(world, build, "job_completed", "webhook", { jobId: job.id });
      await morningChase(world, build);
      const out = await deliver(world, build, "chat_message", "chat", { text: `Chase ${world.invoices[0]?.id} again today`, jobId: job.id });
      for (const d of out?.drafts ?? []) await ownerSendsReminder(world.ports(), d, OWNERS.chase);
    },
    holds: (world) => {
      const KIND = { write_job: "call_received", draft_quote: "job_created", write_invoice: "job_completed" };
      const unattended = (id) => {
        const ev = world.eventById(id);
        return Boolean(ev) && ["webhook", "schedule", "poll"].includes(ev.via);
      };
      const writesOk = writeCalls(world).every((c) => unattended(c.request.trigger) && evName(world, c.request.trigger) === KIND[c.port]);
      const chasesOk = world.chases.length === 1 && world.chases.every((c) => unattended(c.trigger) && evName(world, c.trigger) === "invoice_overdue");
      const chats = world.delivered.filter((e) => e.name === "chat_message").map((e) => e.id);
      const noChatWrite =
        chats.length === 2 &&
        ![...writeCalls(world).map((c) => c.request.trigger), ...world.chases.map((c) => c.trigger), ...world.sends.map((s) => s.trigger)].some((t) => chats.includes(t));
      const allFour = world.jobs.length === 1 && world.quotes.length === 1 && world.invoices.length === 1 && world.chases.length === 1;
      const named =
        evName(world, world.jobs[0]?.trigger) === "call_received" &&
        evName(world, world.quotes[0]?.trigger) === "job_created" &&
        evName(world, world.invoices[0]?.trigger) === "job_completed";
      return writesOk && chasesOk && noChatWrite && allFour && named;
    },
    describe,
  },
  {
    checkId: "exception-owner-travels",
    // 7. Three completed jobs. JS-0701 already carries an exception the quote
    // owner set. JS-0702's invoice write returns no id. JS-0703 is invoiced
    // cleanly, then the invoice owner opens an exception on it before it falls
    // overdue: the chase hop must stop there and name that owner.
    world: () =>
      new CashSeamWorld({
        jobs: [
          { id: "JS-0701", customerName: "H. Held", phone: "+61400000711", status: "complete", exception: { reason: "scope_disputed", owner: OWNERS.quote } },
          { id: "JS-0702", customerName: "I. Null", phone: "+61400000712", status: "complete" },
          { id: "JS-0703", customerName: "J. Later", phone: "+61400000713", status: "complete" },
        ],
        nullInvoiceFor: ["JS-0702"],
      }),
    drive: async (build, world) => {
      await deliver(world, build, "job_completed", "webhook", { jobId: "JS-0701" });
      await deliver(world, build, "job_completed", "webhook", { jobId: "JS-0702" });
      await deliver(world, build, "job_completed", "webhook", { jobId: "JS-0703" });
      world.job("JS-0703").exception = { reason: "customer_queries_hours", owner: OWNERS.invoice };
      await morningChase(world, build);
    },
    holds: (world) => {
      const named = new Set(Object.values(world.owners));
      const hold = world.escalations.some((e) => e.ref === "JS-0701" && e.owner === OWNERS.quote && e.reason === "held_open_exception");
      const failed = world.escalations.some((e) => e.ref === "JS-0702" && e.stage === "invoice" && e.reason === "write_failed" && e.owner === world.owners.invoice);
      const owned = world.escalations.length > 0 && world.escalations.every((e) => e.owner && named.has(e.owner));
      const travels = world.job("JS-0702")?.exception?.owner === world.owners.invoice && world.job("JS-0701")?.exception?.owner === OWNERS.quote;
      const later = world.invoicesFor("JS-0703");
      const chaseStopped =
        later.length === 1 &&
        world.escalations.some((e) => e.stage === "chase" && e.ref === "JS-0703" && e.reason === "held_open_exception" && e.owner === OWNERS.invoice) &&
        !reminders(world).some((e) => e.ref === later[0].id) &&
        world.chases.length === 0;
      return world.invoicesFor("JS-0701").length === 0 && world.invoicesFor("JS-0702").length === 0 && hold && failed && owned && travels && chaseStopped;
    },
    describe,
  },
  {
    checkId: "survives-the-builder",
    // 8. Not a runtime property, and never scored green on a declaration.
    world: () => new CashSeamWorld(),
    drive: () => {},
    holds: () => false,
    describe: () =>
      "Declared: the code is public in mesh/nodes/owing-today, maintained by AI Pathway (digitalgym). The morning schedule and every read run on the business's own ledger and job system accounts. Not scored: the business attaches who else can explain it.",
  },
];

// Check 9 runs on the business's own job system and ledger. with_us on the stub.
export const liveScenarios = [
  {
    checkId: "pass-test",
    world: () => new CashSeamWorld(),
    drive: (build, world) => build(world.ports()),
    holds: () => false,
    describe: (world) => `${world.calls.length} port call(s)`,
  },
];
